            framed, 0, length + 1, reinterpret_cast<const jbyte*>(sensitiveBuffer.data()));
    }

    // Wipe transient sensitive native memory before returning to managed code
    secureZeroMemory(sensitiveBuffer.data(), sensitiveBuffer.size());
    return framed;
}
